import http from 'k6/http';
import { Trend, Rate } from 'k6/metrics';
import { check } from 'k6';

// Custom metrics k6 doesn't track out of the box for streaming/LLM endpoints
const ttft = new Trend('time_to_first_token', true);
const goodput = new Rate('goodput_within_slo');

export const options = {
  scenarios: {
    banking_hours_spike: {
      executor: 'ramping-arrival-rate',
      startRate: 10,
      timeUnit: '1s',
      preAllocatedVUs: 200,
      stages: [
        { target: 50, duration: '2m' },   // normal traffic
        { target: 400, duration: '1m' },  // simulated payday/market-news spike
        { target: 50, duration: '2m' },   // recovery
      ],
    },
  },
  thresholds: {
    time_to_first_token: ['p(95)<800'],
    goodput_within_slo: ['rate>0.98'],
    http_req_failed: ['rate<0.02'],
  },
};

export default function () {
  const start = Date.now();
  const res = http.post('https://api.bank.internal/ai/chat/stream', JSON.stringify({
    prompt: 'What is my current mortgage rate?',
  }), { headers: { 'Content-Type': 'application/json' } });

  const firstByteMs = Date.now() - start; // approximation without full SSE parsing
  ttft.add(firstByteMs);
  goodput.add(firstByteMs < 800 && res.status === 200);

  check(res, { 'status is 200': (r) => r.status === 200 });
}

import pytest
import boto3
import json
import subprocess

@pytest.fixture(scope="session")
def terraform_plan():
    """Run terraform plan in JSON mode so tests can assert on the plan diff, not just apply blindly."""
    subprocess.run(["terraform", "plan", "-out=tfplan.binary"], check=True, cwd="infra/")
    result = subprocess.run(
        ["terraform", "show", "-json", "tfplan.binary"],
        cwd="infra/", capture_output=True, text=True, check=True,
    )
    return json.loads(result.stdout)


@pytest.mark.infra
def test_no_public_s3_buckets_in_plan(terraform_plan):
    for change in terraform_plan["resource_changes"]:
        if change["type"] == "aws_s3_bucket_public_access_block":
            after = change["change"]["after"]
            assert after["block_public_acls"] is True
            assert after["block_public_policy"] is True


@pytest.mark.infra
def test_bedrock_endpoint_region_matches_data_residency_policy(terraform_plan):
    allowed_regions = {"eu-central-1", "me-central-1"}  # bank's approved data residency regions
    for change in terraform_plan["resource_changes"]:
        if change["type"] == "aws_bedrockagent_agent":
            assert change["change"]["after"]["region"] in allowed_regions


@pytest.mark.integration
def test_live_security_group_matches_declared_state():
    """Catch console drift: what's actually deployed vs. what Terraform state says."""
    ec2 = boto3.client("ec2", region_name="eu-central-1")
    sg = ec2.describe_security_groups(GroupIds=["sg-ai-inference-prod"])["SecurityGroups"][0]
    open_ingress = [r for r in sg["IpPermissions"] if any(ip.get("CidrIp") == "0.0.0.0/0" for ip in r.get("IpRanges", []))]
    assert open_ingress == [], "Unexpected public ingress rule found - possible manual drift from Terraform state"


@pytest.mark.parametrize("prompt,expected_min_faithfulness", [
    ("What's the minimum balance for a Platinum account?", 0.85),
    ("How do I dispute a transaction?", 0.85),
])
def test_regression_golden_prompts_still_pass(prompt, expected_min_faithfulness, rag_pipeline, ragas_eval):
    score = ragas_eval(rag_pipeline.answer(prompt))
    assert score["faithfulness"] >= expected_min_faithfulness
